fn decode_message_type_from_decoder<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
) -> NifResult<Term<'a>> {
    match decoder.read_var_uint() {
        Ok(raw) => {
            match raw as i64 {
                0i64 => {
                    Ok(cached_atom(env, &MESSAGE_TYPE_ATOM_0, "join_start").encode(env))
                }
                1i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_1, "node_changes")
                            .encode(env),
                    )
                }
                2i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_2, "user_changes")
                            .encode(env),
                    )
                }
                3i64 => {
                    Ok(cached_atom(env, &MESSAGE_TYPE_ATOM_3, "join_end").encode(env))
                }
                4i64 => Ok(cached_atom(env, &MESSAGE_TYPE_ATOM_4, "signal").encode(env)),
                5i64 => Ok(cached_atom(env, &MESSAGE_TYPE_ATOM_5, "style").encode(env)),
                6i64 => {
                    Ok(cached_atom(env, &MESSAGE_TYPE_ATOM_6, "style_set").encode(env))
                }
                7i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_7, "join_start_skip_reload")
                            .encode(env),
                    )
                }
                8i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_8, "notify_should_upgrade")
                            .encode(env),
                    )
                }
                9i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_9, "upgrade_done")
                            .encode(env),
                    )
                }
                10i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_10, "upgrade_refresh")
                            .encode(env),
                    )
                }
                11i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_11, "scene_graph_query")
                            .encode(env),
                    )
                }
                12i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_12, "scene_graph_reply")
                            .encode(env),
                    )
                }
                13i64 => Ok(cached_atom(env, &MESSAGE_TYPE_ATOM_13, "diff").encode(env)),
                14i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_14, "client_broadcast")
                            .encode(env),
                    )
                }
                15i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_15, "join_start_journaled")
                            .encode(env),
                    )
                }
                16i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_16, "stream_start")
                            .encode(env),
                    )
                }
                17i64 => {
                    Ok(cached_atom(env, &MESSAGE_TYPE_ATOM_17, "stream_end").encode(env))
                }
                18i64 => {
                    Ok(
                        cached_atom(
                                env,
                                &MESSAGE_TYPE_ATOM_18,
                                "interactive_slide_change",
                            )
                            .encode(env),
                    )
                }
                19i64 => {
                    Ok(
                        cached_atom(
                                env,
                                &MESSAGE_TYPE_ATOM_19,
                                "reconnect_scene_graph_query",
                            )
                            .encode(env),
                    )
                }
                20i64 => {
                    Ok(
                        cached_atom(
                                env,
                                &MESSAGE_TYPE_ATOM_20,
                                "reconnect_scene_graph_reply",
                            )
                            .encode(env),
                    )
                }
                21i64 => {
                    Ok(
                        cached_atom(
                                env,
                                &MESSAGE_TYPE_ATOM_21,
                                "join_end_incremental_reconnect",
                            )
                            .encode(env),
                    )
                }
                22i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_22, "node_status_change")
                            .encode(env),
                    )
                }
                23i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_23, "client_rendered")
                            .encode(env),
                    )
                }
                24i64 => {
                    Ok(
                        cached_atom(env, &MESSAGE_TYPE_ATOM_24, "buzz_approval_change")
                            .encode(env),
                    )
                }
                value => Ok(value.encode(env)),
            }
        }
        Err(reason) => Err(reason),
    }
}


