fn decode_transform_modifier_type_from_decoder<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
) -> NifResult<Term<'a>> {
    match decoder.read_var_uint() {
        Ok(raw) => {
            match raw as i64 {
                0i64 => {
                    Ok(
                        cached_atom(env, &TRANSFORM_MODIFIER_TYPE_ATOM_0, "repeat")
                            .encode(env),
                    )
                }
                1i64 => {
                    Ok(
                        cached_atom(env, &TRANSFORM_MODIFIER_TYPE_ATOM_1, "symmetry")
                            .encode(env),
                    )
                }
                2i64 => {
                    Ok(
                        cached_atom(env, &TRANSFORM_MODIFIER_TYPE_ATOM_2, "skew")
                            .encode(env),
                    )
                }
                value => Ok(value.encode(env)),
            }
        }
        Err(reason) => Err(reason),
    }
}


