fn decode_variable_any_value_from_decoder<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
) -> NifResult<Term<'a>> {
    let module_atom = cached_atom(
        env,
        &VARIABLE_ANY_VALUE_MODULE_ATOM,
        "Elixir.Figler.Schema.VariableAnyValue",
    );
    let keys = cached_struct_keys(
        env,
        &VARIABLE_ANY_VALUE_STRUCT_KEYS,
        &[
            "bool_value",
            "text_value",
            "float_value",
            "alias",
            "color_value",
            "expression_value",
            "map_value",
            "symbol_id_value",
            "font_style_value",
            "text_data_value",
            "node_field_alias_value",
            "cms_alias_value",
            "prop_ref_value",
            "image_value",
            "managed_string_alias_value",
            "link_value",
            "js_runtime_alias_value",
            "slot_content_id_value",
            "keyframe_track_id_value",
            "keyframe_track_parameter_value",
            "easing_value",
            "vector_value",
            "color_array_value",
            "line_value",
            "circle_value",
            "rotation3_d_value",
            "circle_point_value",
            "gradient_value",
            "color_point_value",
        ],
    );
    let values = default_struct_values(env, module_atom, keys.len() - 1);
    decode_variable_any_value_fields_from_decoder(env, decoder, keys, values)
}


