fn decode_sparse_color_stop_var_from_decoder<'a>(
    env: Env<'a>,
    decoder: &mut Decoder<'_>,
) -> NifResult<Term<'a>> {
    static MODULE_ATOM: OnceLock<Atom> = OnceLock::new();
    static MODULE_KEY_ATOM: OnceLock<Atom> = OnceLock::new();
    let module_atom = cached_atom(
        env,
        &MODULE_ATOM,
        "Elixir.Figler.Schema.ColorStopVar",
    );
    let module_key_atom = cached_atom(env, &MODULE_KEY_ATOM, "__kiwi_module__");
    let definition_name = "ColorStopVar";
    let mut keys = Vec::with_capacity(4);
    let mut values = Vec::with_capacity(4);
    keys.push(module_key_atom.encode(env));
    values.push(module_atom.encode(env));
    loop {
        match decoder.read_var_uint()? {
            0 => break,
            1 => {
                static FIELD_ATOM_1: OnceLock<Atom> = OnceLock::new();
                let field_atom = cached_atom(env, &FIELD_ATOM_1, "color");
                let value = decode_sparse_color_from_decoder(env, decoder)?;
                keys.push(field_atom.encode(env));
                values.push(value);
            }
            2 => {
                static FIELD_ATOM_2: OnceLock<Atom> = OnceLock::new();
                let field_atom = cached_atom(env, &FIELD_ATOM_2, "color_var");
                let value = decode_sparse_variable_data_from_decoder(env, decoder)?;
                keys.push(field_atom.encode(env));
                values.push(value);
            }
            3 => {
                static FIELD_ATOM_3: OnceLock<Atom> = OnceLock::new();
                let field_atom = cached_atom(env, &FIELD_ATOM_3, "position");
                let value = decoder.read_var_float(env)?;
                keys.push(field_atom.encode(env));
                values.push(value);
            }
            field => {
                return Err(
                    Error::Term(
                        Box::new(
                            format!(
                                "unknown field {} while decoding sparse {}", field,
                                definition_name
                            ),
                        ),
                    ),
                );
            }
        }
    }
    Term::map_from_term_arrays(env, &keys, &values)
}
